--
-- Name: business_transaction_type; Type: TYPE; Schema: public; Owner: postgres
--

CREATE TYPE finance.business_transaction_type AS ENUM (
    'sale',
    'purchase',
    'expense'
);

--
-- Name: apply_bill_stock(uuid, finance.business_transaction_type, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.apply_bill_stock(p_owner uuid, p_type finance.business_transaction_type, p_items jsonb, p_sign integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare it jsonb; delta numeric;
begin
  if p_type not in ('sale', 'purchase') then return; end if;
  for it in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    delta := coalesce((it ->> 'qty')::numeric, 0) * p_sign * case when p_type = 'sale' then -1 else 1 end;
    if delta <> 0 then
      update finance.products
         set stock_level = stock_level + delta
       where owner_id = p_owner
         and lower(btrim(name)) = lower(btrim(it ->> 'description'));
    end if;
  end loop;
end $$;

--
-- Name: business_transactions_stock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.business_transactions_stock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform finance.apply_bill_stock(old.owner_id, old.type, old.items, -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform finance.apply_bill_stock(new.owner_id, new.type, new.items, 1);
  end if;
  return coalesce(new, old);
end $$;

