CREATE FUNCTION finance.finance_apply_jageer_bill(p_secret text, p_op text, p_email text, p_bill jsonb, p_party jsonb DEFAULT NULL::jsonb, p_bank_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'finance', 'extensions'
    AS $$
