$$;

--
-- Name: finance_apply_jageer_record(text, text, text, text, jsonb, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_apply_jageer_record(p_secret text, p_op text, p_email text, p_kind text, p_row jsonb, p_party jsonb DEFAULT NULL::jsonb, p_bank jsonb DEFAULT NULL::jsonb, p_bank2 jsonb DEFAULT NULL::jsonb, p_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance', 'extensions'
    AS $$
declare
  v_owner uuid;
  v_id    uuid;
  v_party uuid;
  v_bank  uuid;
  v_bank2 uuid;
  v_cat   uuid;
  v_type  text;
  v_mode  text;
  v_items jsonb;
  v_src   text;
begin
  perform finance.finance_jageer_check_secret(p_secret);

  v_id := nullif(p_row ->> 'id', '')::uuid;
  if v_id is null then
    raise exception 'record id missing';
  end if;
  if p_op not in ('upsert', 'delete') then
    raise exception 'unknown operation %', p_op;
  end if;

  v_owner := finance.finance_jageer_owner(p_email);
  if v_owner is null then
    return jsonb_build_object('status', 'skipped', 'reason', 'no confirmed Finance account for this email');
  end if;

  -- ------------------------------------------------------------ bills
  if p_kind = 'bill' then
    if p_op = 'delete' then
      delete from finance.business_transactions
       where owner_id = v_owner and source_type = 'jageer' and source_id = v_id;
      return jsonb_build_object('status', 'deleted');
    end if;

    v_type := p_row ->> 'type';
    if v_type is null or v_type not in ('sale', 'purchase', 'expense') then
      raise exception 'unknown bill type';
    end if;

    v_party := finance.finance_jageer_party(v_owner, p_party);
    v_bank  := finance.finance_jageer_bank(v_owner, p_bank);
    v_cat   := case when v_type = 'expense' then finance.finance_jageer_category(v_owner, p_category) end;
    v_mode  := case when (p_row ->> 'payment_mode') in ('cash', 'bank') then p_row ->> 'payment_mode' else 'cash' end;
    v_items := case when jsonb_typeof(p_row -> 'items') = 'array' then p_row -> 'items' else '[]'::jsonb end;

    insert into finance.business_transactions
      (owner_id, type, amount, note, party_name, customer_id, bill_no, bill_date,
       party_address, vat_pan_no, items, discount_amount, vat_amount,
       expense_category_id, payment_mode, bank_account_id, source_type, source_id, created_at)
    values
      (v_owner, v_type::finance.business_transaction_type, (p_row ->> 'amount')::numeric,
       p_row ->> 'note', p_row ->> 'party_name', v_party, p_row ->> 'bill_no',
       nullif(p_row ->> 'bill_date', '')::date, p_row ->> 'party_address', p_row ->> 'vat_pan_no',
       v_items, coalesce((p_row ->> 'discount_amount')::numeric, 0), coalesce((p_row ->> 'vat_amount')::numeric, 0),
       v_cat, v_mode, v_bank, 'jageer', v_id,
       coalesce(nullif(p_row ->> 'created_at', '')::timestamptz, now()))
    on conflict (source_type, source_id) where source_type is not null and source_id is not null
    do update set
      type                = excluded.type,
      amount              = excluded.amount,
      note                = excluded.note,
      party_name          = excluded.party_name,
      customer_id         = excluded.customer_id,
      bill_no             = excluded.bill_no,
      bill_date           = excluded.bill_date,
      party_address       = excluded.party_address,
      vat_pan_no          = excluded.vat_pan_no,
      items               = excluded.items,
      discount_amount     = excluded.discount_amount,
      vat_amount          = excluded.vat_amount,
      expense_category_id = excluded.expense_category_id,
      payment_mode        = excluded.payment_mode,
      bank_account_id     = excluded.bank_account_id,
      updated_at          = now()
    where finance.business_transactions.owner_id = excluded.owner_id;

    return jsonb_build_object('status', 'saved');
  end if;

  -- -------------------------------------------------------- customers
  if p_kind = 'customer' then
    if p_op = 'delete' then
      delete from finance.customers
       where owner_id = v_owner and external_source = 'jageer' and external_id = v_id;
      return jsonb_build_object('status', 'deleted');
    end if;
    v_party := finance.finance_jageer_party(v_owner, p_row);
    return jsonb_build_object('status', case when v_party is null then 'skipped' else 'saved' end);
  end if;

  -- ----------------------------------------------------- bank accounts
  if p_kind = 'bank_account' then
    if p_op = 'delete' then
      delete from finance.bank_accounts
       where owner_id = v_owner and external_source = 'jageer' and external_id = v_id;
      return jsonb_build_object('status', 'deleted');
    end if;
    v_bank := finance.finance_jageer_bank(v_owner, p_row);
    return jsonb_build_object('status', case when v_bank is null then 'skipped' else 'saved' end);
  end if;

  -- ------------------------------------------------------ ledger entries
  if p_kind in ('customer_entry', 'vendor_entry') then
    v_src := case when p_kind = 'customer_entry' then 'jageer_customer_entry' else 'jageer_vendor_entry' end;

    if p_op = 'delete' then
      if p_kind = 'customer_entry' then
        delete from finance.customer_ledger_entries
         where owner_id = v_owner and source_type = v_src and source_id = v_id;
      else
        delete from finance.vendor_ledger_entries
         where owner_id = v_owner and source_type = v_src and source_id = v_id;
      end if;
      return jsonb_build_object('status', 'deleted');
    end if;

    v_party := finance.finance_jageer_party(v_owner, p_party);
    if v_party is null then
      return jsonb_build_object('status', 'skipped', 'reason', 'entry has no customer or vendor');
    end if;
    v_bank := finance.finance_jageer_bank(v_owner, p_bank);

    if p_kind = 'customer_entry' then
      insert into finance.customer_ledger_entries
        (customer_id, owner_id, entry_type, amount, note, source, source_type, source_id,
         bank_account_id, entry_date, receipt_no, created_at)
      values
        (v_party, v_owner, p_row ->> 'entry_type', (p_row ->> 'amount')::numeric, p_row ->> 'note',
         case when (p_row ->> 'source') in ('manual', 'booking') then p_row ->> 'source' else 'manual' end,
         v_src, v_id, v_bank, nullif(p_row ->> 'entry_date', '')::date, p_row ->> 'receipt_no',
         coalesce(nullif(p_row ->> 'created_at', '')::timestamptz, now()))
      on conflict (source_type, source_id) where source_type is not null and source_id is not null
      do update set
        customer_id     = excluded.customer_id,
        entry_type      = excluded.entry_type,
        amount          = excluded.amount,
        note            = excluded.note,
        source          = excluded.source,
        bank_account_id = excluded.bank_account_id,
        entry_date      = excluded.entry_date,
        receipt_no      = excluded.receipt_no
      where finance.customer_ledger_entries.owner_id = excluded.owner_id;
    else
      insert into finance.vendor_ledger_entries
        (vendor_id, owner_id, entry_type, amount, note, source, source_type, source_id,
         bank_account_id, entry_date, receipt_no, created_at)
      values
        (v_party, v_owner, p_row ->> 'entry_type', (p_row ->> 'amount')::numeric, p_row ->> 'note',
         case when (p_row ->> 'source') in ('manual', 'booking') then p_row ->> 'source' else 'manual' end,
         v_src, v_id, v_bank, nullif(p_row ->> 'entry_date', '')::date, p_row ->> 'receipt_no',
         coalesce(nullif(p_row ->> 'created_at', '')::timestamptz, now()))
      on conflict (source_type, source_id) where source_type is not null and source_id is not null
      do update set
        vendor_id       = excluded.vendor_id,
        entry_type      = excluded.entry_type,
        amount          = excluded.amount,
        note            = excluded.note,
        source          = excluded.source,
        bank_account_id = excluded.bank_account_id,
        entry_date      = excluded.entry_date,
        receipt_no      = excluded.receipt_no
      where finance.vendor_ledger_entries.owner_id = excluded.owner_id;
    end if;

    return jsonb_build_object('status', 'saved');
  end if;

  -- ----------------------------------------------------------- transfers
  if p_kind = 'transfer' then
    if p_op = 'delete' then
      delete from finance.account_transfers
       where owner_id = v_owner and external_source = 'jageer' and external_id = v_id;
      return jsonb_build_object('status', 'deleted');
    end if;

    v_bank  := finance.finance_jageer_bank(v_owner, p_bank);
    v_bank2 := finance.finance_jageer_bank(v_owner, p_bank2);
    if v_bank is null or v_bank2 is null or v_bank = v_bank2 then
      return jsonb_build_object('status', 'skipped', 'reason', 'transfer needs two different accounts');
    end if;

    insert into finance.account_transfers
      (owner_id, from_account_id, to_account_id, amount, note, transfer_date, created_at,
       external_source, external_id)
    values
      (v_owner, v_bank, v_bank2, (p_row ->> 'amount')::numeric, p_row ->> 'note',
       coalesce(nullif(p_row ->> 'transfer_date', '')::date, current_date),
       coalesce(nullif(p_row ->> 'created_at', '')::timestamptz, now()),
       'jageer', v_id)
    on conflict (owner_id, external_source, external_id) where external_source is not null and external_id is not null
    do update set
      from_account_id = excluded.from_account_id,
      to_account_id   = excluded.to_account_id,
      amount          = excluded.amount,
      note            = excluded.note,
      transfer_date   = excluded.transfer_date;

    return jsonb_build_object('status', 'saved');
  end if;

  raise exception 'unknown kind %', p_kind;
end;
$$;

