-- Name: finance_is_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
  -- Jageer's version: select coalesce((select role = 'admin' from finance.profiles where id = auth.uid()), false);
  -- Department store: no back-office admin; every owner sees only their own books.
  select false;
$$;

--
-- Name: finance_jageer_bank(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_jageer_bank(p_owner uuid, p_bank jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
declare
  v_ext  uuid := nullif(p_bank ->> 'id', '')::uuid;
  v_name text := nullif(btrim(p_bank ->> 'name'), '');
  v_id   uuid;
begin
  if p_bank is null or v_name is null then
    return null;
  end if;

  if v_ext is not null then
    select b.id into v_id from finance.bank_accounts b
     where b.owner_id = p_owner and b.external_source = 'jageer' and b.external_id = v_ext;
  end if;

  if v_id is null then
    select b.id into v_id from finance.bank_accounts b
     where b.owner_id = p_owner and lower(b.name) = lower(v_name)
       and (v_ext is null or b.external_id is null)
     limit 1;
  end if;

  if v_id is not null then
    if v_ext is not null then
      update finance.bank_accounts b
         set external_source = 'jageer',
             external_id     = v_ext,
             -- a rename is applied unless another account already has that name
             name = case when exists (
                      select 1 from finance.bank_accounts o
                       where o.owner_id = p_owner and lower(o.name) = lower(v_name) and o.id <> v_id)
                    then b.name else v_name end
       where b.id = v_id;
    end if;
    return v_id;
  end if;

  insert into finance.bank_accounts (owner_id, name, external_source, external_id)
  values (p_owner, v_name, case when v_ext is not null then 'jageer' end, v_ext)
  returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: finance_jageer_category(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_jageer_category(p_owner uuid, p_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
declare
  v_name text := nullif(btrim(p_name), '');
  v_id   uuid;
begin
  if v_name is null then
    return null;
  end if;
  select c.id into v_id from finance.expense_categories c
   where c.owner_id = p_owner and lower(c.name) = lower(v_name);
  if v_id is null then
    insert into finance.expense_categories (owner_id, name) values (p_owner, v_name) returning id into v_id;
  end if;
  return v_id;
end;
$$;

--
-- Name: finance_jageer_check_secret(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_jageer_check_secret(p_secret text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance', 'extensions'
    AS $$
begin
  if p_secret is null or not exists (
    select 1 from finance.finance_sync_secrets s
     where s.name = 'jageer'
       and s.secret_hash = encode(digest(p_secret, 'sha256'), 'hex')
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: finance_jageer_owner(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_jageer_owner(p_email text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
  select u.id
    from auth.users u
   where lower(u.email) = lower(btrim(p_email))
     and u.email_confirmed_at is not null
   order by u.created_at
   limit 1;
$$;

--
-- Name: finance_jageer_party(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_jageer_party(p_owner uuid, p_party jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
declare
  v_ext      uuid := nullif(p_party ->> 'id', '')::uuid;
  v_name     text := nullif(btrim(p_party ->> 'name'), '');
  v_phone    text := nullif(btrim(p_party ->> 'phone'), '');
  v_id       uuid;
  v_conflict boolean := false;
begin
  if p_party is null or v_ext is null or v_name is null then
    return null;
  end if;

  select c.id into v_id from finance.customers c
   where c.owner_id = p_owner and c.external_source = 'jageer' and c.external_id = v_ext;

  if v_id is null and v_phone is not null then
    select c.id into v_id from finance.customers c
     where c.owner_id = p_owner and c.phone = v_phone and c.external_id is null limit 1;
  end if;

  if v_id is null then
    select c.id into v_id from finance.customers c
     where c.owner_id = p_owner and lower(btrim(c.name)) = lower(v_name) and c.external_id is null
     order by c.created_at limit 1;
  end if;

  -- One party per phone per book: if another party already has this number,
  -- leave the phone alone rather than fail the whole record.
  if v_phone is not null then
    v_conflict := exists (
      select 1 from finance.customers c
       where c.owner_id = p_owner and c.phone = v_phone and c.id is distinct from v_id);
  end if;

  if v_id is not null then
    update finance.customers
       set external_source = 'jageer',
           external_id     = v_ext,
           name            = v_name,
           phone           = case when v_conflict then phone else v_phone end,
           address         = nullif(p_party ->> 'address', ''),
           latitude        = nullif(p_party ->> 'latitude', '')::double precision,
           longitude       = nullif(p_party ->> 'longitude', '')::double precision,
           contact_person_name  = nullif(p_party ->> 'contact_person_name', ''),
           contact_person_phone = nullif(p_party ->> 'contact_person_phone', '')
     where id = v_id;
    return v_id;
  end if;

  insert into finance.customers
    (owner_id, name, phone, address, latitude, longitude,
     contact_person_name, contact_person_phone, external_source, external_id)
  values
    (p_owner, v_name, case when v_conflict then null else v_phone end,
     nullif(p_party ->> 'address', ''),
     nullif(p_party ->> 'latitude', '')::double precision,
     nullif(p_party ->> 'longitude', '')::double precision,
     nullif(p_party ->> 'contact_person_name', ''),
     nullif(p_party ->> 'contact_person_phone', ''),
     'jageer', v_ext)
  returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: finance_set_sync_secret(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_set_sync_secret(p_name text DEFAULT 'jageer'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance', 'extensions'
    AS $$
declare
  v_secret text := encode(gen_random_bytes(32), 'hex');
begin
  insert into finance.finance_sync_secrets (name, secret_hash)
  values (p_name, encode(digest(v_secret, 'sha256'), 'hex'))
  on conflict (name) do update set secret_hash = excluded.secret_hash, created_at = now();
  return v_secret;
end;
$$;

--
-- Name: finance_stamp_owner(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.finance_stamp_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  if new.owner_id is null then
    new.owner_id := finance.finance_current_owner();
  end if;
  if new.owner_id is null then
    raise exception 'owner_id could not be determined for this insert';
  end if;
  return new;
end;
$$;

