    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  insert into finance.profiles (id, full_name, phone, business_name, business_address, business_phone)
  values (
    new.id,
    new.raw_user_meta_data ->> 'full_name',
    nullif(btrim(new.raw_user_meta_data ->> 'business_phone'), ''),
    nullif(btrim(new.raw_user_meta_data ->> 'business_name'), ''),
    nullif(btrim(new.raw_user_meta_data ->> 'business_address'), ''),
    nullif(btrim(new.raw_user_meta_data ->> 'business_phone'), '')
  )
  on conflict (id) do nothing;
  return new;
end $$;

--
-- Name: party_type_id_for(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.party_type_id_for(p_owner uuid, p_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
declare tid uuid;
begin
  select id into tid from party_types where owner_id = p_owner and lower(btrim(name)) = lower(p_name) order by created_at limit 1;
  if tid is null then
    insert into party_types (owner_id, name) values (p_owner, p_name) on conflict (owner_id, name) do nothing returning id into tid;
    if tid is null then
      select id into tid from party_types where owner_id = p_owner and name = p_name;
    end if;
  end if;
  return tid;
end $$;

--
-- Name: rental_wage_rows(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.rental_wage_rows(p_owner uuid) RETURNS TABLE(owner_id uuid, employee_id uuid, day date, amount numeric, note text, source_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
  select r.owner_id, r.customer_id, d::date, r.rate_per_day,
         'Daily rent · ' || r.car,
         md5('rental_wage:' || r.id::text || ':' || d::date::text)::uuid
    from finance.rentals r
   cross join lateral generate_series(
           r.start_date,
           least(coalesce(r.returned_on, (now() at time zone 'Asia/Kathmandu')::date), (now() at time zone 'Asia/Kathmandu')::date),
           interval '1 day') d
   where r.customer_id is not null and r.rate_per_day > 0
     and (p_owner is null or r.owner_id = p_owner)
$$;

--
-- Name: sync_purchase_credit_to_vendor_ledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.sync_purchase_credit_to_vendor_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from vendor_ledger_entries
     where source_type = 'business_transaction' and source_id = old.id;
    return old;
  end if;

  if new.type = 'purchase' and new.customer_id is not null and new.amount > 0 then
    insert into vendor_ledger_entries
      (vendor_id, owner_id, entry_type, amount, note, source, source_type, source_id, entry_date)
    values
      (new.customer_id, new.owner_id, 'debit', new.amount, new.note, 'booking',
       'business_transaction', new.id, new.bill_date)
    on conflict (source_type, source_id) where source_type is not null and source_id is not null
    do update set amount     = excluded.amount,
                  vendor_id  = excluded.vendor_id,
                  note       = excluded.note,
                  entry_date = excluded.entry_date;
  else
    delete from vendor_ledger_entries
     where source_type = 'business_transaction' and source_id = new.id;
  end if;

  return new;
end;
$$;

--
-- Name: sync_rental_wages(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.sync_rental_wages() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  if auth.uid() is null then return; end if;
  perform finance.sync_rental_wages_for(auth.uid());
end $$;

--
-- Name: sync_rental_wages_for(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.sync_rental_wages_for(p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  delete from finance.vendor_ledger_entries v
   where v.source_type = 'rental_wage' and (p_owner is null or v.owner_id = p_owner);
  delete from finance.customer_ledger_entries c
   where c.source_type = 'rental_wage'
     and (p_owner is null or c.owner_id = p_owner)
     and (c.source_id, c.customer_id) not in (select w.source_id, w.employee_id from finance.rental_wage_rows(p_owner) w);
  insert into finance.customer_ledger_entries (customer_id, owner_id, entry_type, amount, note, source, source_type, source_id, entry_date)
  select w.employee_id, w.owner_id, 'debit', w.amount, w.note, 'booking', 'rental_wage', w.source_id, w.day
    from finance.rental_wage_rows(p_owner) w
  on conflict (source_type, source_id) where source_type is not null and source_id is not null
  do update set amount = excluded.amount, customer_id = excluded.customer_id, note = excluded.note, entry_date = excluded.entry_date;
end $$;

--
-- Name: sync_sale_to_customer_ledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.sync_sale_to_customer_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
begin
  if tg_op = 'DELETE' then
    delete from customer_ledger_entries
     where source_type = 'business_transaction' and source_id = old.id;
    return old;
  end if;

  if new.type = 'sale' and new.customer_id is not null and new.amount > 0 then
    insert into customer_ledger_entries
      (customer_id, owner_id, entry_type, amount, note, source, source_type, source_id, entry_date)
    values
      (new.customer_id, new.owner_id, 'debit', new.amount, new.note, 'booking',
       'business_transaction', new.id, new.bill_date)
    on conflict (source_type, source_id) where source_type is not null and source_id is not null
    do update set amount      = excluded.amount,
                  customer_id = excluded.customer_id,
                  note        = excluded.note,
                  entry_date  = excluded.entry_date;
  else
    -- Type or party changed away from "sale to a saved customer": the
    -- debt this bill used to book is no longer real.
    delete from customer_ledger_entries
     where source_type = 'business_transaction' and source_id = new.id;
  end if;

  return new;
end;
$$;

--
-- Name: type_party_from_ledger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION finance.type_party_from_ledger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'finance'
    AS $$
declare
  pid  uuid;
  kind text;
begin
  -- Read the party field through jsonb: a vendor entry has no customer_id and a customer entry no vendor_id.
  if tg_table_name = 'customer_ledger_entries' then
    pid := (to_jsonb(new) ->> 'customer_id')::uuid;
    kind := 'Customer';
  else
    pid := (to_jsonb(new) ->> 'vendor_id')::uuid;
    kind := 'Vendor';
  end if;
  update customers
     set party_type_id = party_type_id_for(new.owner_id, kind)
   where id = pid and party_type_id is null;
  return new;
end $$;

