CREATE POLICY vendor_ledger_entries_update_manual ON finance.vendor_ledger_entries FOR UPDATE USING (((owner_id = finance.finance_current_owner()) AND (source = 'manual'::text))) WITH CHECK (((owner_id = finance.finance_current_owner()) AND (source = 'manual'::text)));

